#include <cassert>
#include <iostream>
#include "../src/TrainingPilotList.h"
struct Tag{int altitude=11000,ias=230,heading=331;std::string owner="TEACHER_CTR",scratchpad=" R",nextFix="KIREX",altMode="ALT",speedMode="IAS",navMode="HDG",values[8]={"8000","170","333","2250","KIREX","2101","CLEAR","0.78"},states[8]={"done","done","done","done","done","done","done","done"};bool matches[8]{};};
int main(){using namespace TrainingPilotList;Tag a;assert(Value(Altitude,a).text=="110");assert(Value(IAS,a).text=="230");assert(Value(Heading,a).text=="331");assert(Value(PilotAltitude,a).text=="080");assert(Value(PilotAltitude,a).tone==1);a.matches[0]=true;assert(Value(PilotAltitude,a).text=="080+");assert(Value(PilotAltitude,a).tone==2);a.states[0]="error";assert(Value(PilotAltitude,a).text=="080!");assert(Value(PilotAltitude,a).tone==3);assert(Value(PilotSpeed,a).text=="170");a.speedMode="MACH";assert(Value(PilotSpeed,a).text=="M0.78");a.altMode="APP";assert(Value(PilotAltitude,a).text=="APR");a.navMode="DCT";assert(Value(PilotNavigation,a).text=="KIREX");a.navMode="HDG";a.values[2]="PRESENT";assert(Value(PilotNavigation,a).text=="PRES");a.values[2]="-";assert(Value(PilotNavigation,a).text=="-");assert(Value(Owner,a).text=="TEACHER_CTR");assert(Value(SFI,a).text=="R");assert(Value(NextFix,a).text=="KIREX");std::cout<<"PASS independent instructor-list actual/target fields, colours/states, Mach, approach, owner and SFI.\n";}
